def decode_string(s):
    def find_matching_bracket(start):
        depth = 0
        for i in range(start, len(s)):                          # rescans forward to find the matching bracket
            if s[i] == '[':
                depth += 1
            elif s[i] == ']':
                depth -= 1
                if depth == 0:
                    return i
        return -1

    def decode(i, end):
        result = ""
        while i < end:
            if s[i].isdigit():
                num_start = i
                while s[i].isdigit():
                    i += 1
                count = int(s[num_start:i])
                close = find_matching_bracket(i)                     # search for the matching bracket every time
                inner = decode(i + 1, close)
                result += inner * count
                i = close + 1
            else:
                result += s[i]
                i += 1
        return result

    return decode(0, len(s))


if __name__ == "__main__":
    s = "3[a2[c]]"
    print(decode_string(s))

