public class Main {
    String decodeString(String s) {
        return decode(s, new int[]{0});
    }

    String decode(String s, int[] pos) {
        StringBuilder result = new StringBuilder();
        while (pos[0] < s.length() && s.charAt(pos[0]) != ']') {
            if (Character.isDigit(s.charAt(pos[0]))) {
                int count = 0;
                while (Character.isDigit(s.charAt(pos[0]))) {
                    count = count * 10 + (s.charAt(pos[0]) - '0');
                    pos[0]++;
                }
                pos[0]++;                                                 // skip the opening bracket
                String inner = decode(s, pos);                              // recursively decode the inner content
                pos[0]++;                                                    // skip the matching closing bracket
                for (int i = 0; i < count; i++) result.append(inner);
            } else {
                result.append(s.charAt(pos[0]));
                pos[0]++;
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        String s = "3[a2[c]]";
        Main solution = new Main();
        System.out.println(solution.decodeString(s));
    }
}

