def decode_string(s):
    stack = []                                              # each entry is (count, string built before this level)
    current = ""
    count = 0
    for ch in s:
        if ch.isdigit():
            count = count * 10 + int(ch)
        elif ch == '[':
            stack.append((count, current))                      # save this level's state before going deeper
            current = ""
            count = 0
        elif ch == ']':
            previous_count, previous_string = stack.pop()
            current = previous_string + current * previous_count   # repeat and reattach to the outer level
        else:
            current += ch
    return current


