import java.util.*;

public class Main {
    String decodeString(String s) {
        Deque<Integer> countStack = new ArrayDeque<>();
        Deque<String> stringStack = new ArrayDeque<>();             // each entry is the string built before this level
        StringBuilder current = new StringBuilder();
        int count = 0;
        for (char ch : s.toCharArray()) {
            if (Character.isDigit(ch)) {
                count = count * 10 + (ch - '0');
            } else if (ch == '[') {
                countStack.push(count);
                stringStack.push(current.toString());                    // save this level's state before going deeper
                current = new StringBuilder();
                count = 0;
            } else if (ch == ']') {
                int previousCount = countStack.pop();
                StringBuilder previousString = new StringBuilder(stringStack.pop());
                for (int i = 0; i < previousCount; i++) previousString.append(current);
                current = previousString;                                    // repeat and reattach to the outer level
            } else {
                current.append(ch);
            }
        }
        return current.toString();
    }

    public static void main(String[] args) {
        String s = "3[a2[c]]";
        Main solution = new Main();
        System.out.println(solution.decodeString(s));
    }
}

