#include <bits/stdc++.h>
using namespace std;

string decodeString(string s) {
    stack<int> countStack;
    stack<string> stringStack;                                    // each entry is the string built before this level
    string current = "";
    int count = 0;
    for (char ch : s) {
        if (isdigit(ch)) {
            count = count * 10 + (ch - '0');
        } else if (ch == '[') {
            countStack.push(count);
            stringStack.push(current);                                 // save this level's state before going deeper
            current = "";
            count = 0;
        } else if (ch == ']') {
            int previousCount = countStack.top(); countStack.pop();
            string previousString = stringStack.top(); stringStack.pop();
            string repeated;
            for (int i = 0; i < previousCount; i++) repeated += current;
            current = previousString + repeated;                           // repeat and reattach to the outer level
        } else {
            current += ch;
        }
    }
    return current;
}

int main() {
    string s = "3[a2[c]]";
    cout << decodeString(s) << endl;
    return 0;
